/**
 * /api/businesses/:businessId/customers
 * PUT /:id creates or replaces (ids are generated by the web app); POST / lets the server pick the id.
 * Deleting a customer never touches invoices: they keep their own buyer snapshot.
 */
import crypto from 'node:crypto';
import { asc, eq } from 'drizzle-orm';
import { Router, type Request, type Response } from 'express';
import { requireAuth, requireBusiness, requireRole } from '../lib/auth.js';
import { businessIdOf, inBusiness, notFound, parse, pgCode, PG, param } from '../lib/http.js';
import { customers } from '../db/schema.js';
import { Id } from '../schemas/common.js';
import { CustomerInput } from '../schemas/masters.js';

export const customerRoutes = Router({ mergeParams: true });
customerRoutes.use(requireAuth, requireBusiness);
const canWrite = requireRole('owner', 'accountant');

type Row = typeof customers.$inferSelect;
export const toCustomerDto = (c: Row) => ({
  id: c.id, businessId: c.businessId, ntnCnic: c.ntnCnic, name: c.name, province: c.province, address: c.address,
  registrationType: c.registrationType, phone: c.phone ?? undefined, email: c.email ?? undefined, activeStatus: c.activeStatus ?? undefined,
});

customerRoutes.get('/', async (req, res) => {
  const rows = await inBusiness(req, tx => tx.select().from(customers).orderBy(asc(customers.name)));
  res.json(rows.map(toCustomerDto));
});

customerRoutes.get('/:id', async (req, res) => {
  const [row] = await inBusiness(req, tx => tx.select().from(customers).where(eq(customers.id, param(req, 'id'))));
  return row ? res.json(toCustomerDto(row)) : notFound(res, 'Customer');
});

async function save(req: Request, res: Response, id: string, created: number) {
  if (!Id.safeParse(id).success) return res.status(400).json({ code: 'VALIDATION', message: 'Invalid id', issues: [{ path: 'id', message: 'Invalid id' }] });
  const body = parse(CustomerInput, req.body, res); if (!body) return;
  const { id: _ignored, ...fields } = body;
  const values = { ...fields, phone: fields.phone || null, email: fields.email || null, activeStatus: fields.activeStatus ?? null, updatedAt: new Date() };
  try {
    const [row] = await inBusiness(req, tx => tx.insert(customers).values({ id, businessId: businessIdOf(req), ...values })
      .onConflictDoUpdate({ target: customers.id, set: values }).returning());
    res.status(created).json(toCustomerDto(row!));
  } catch (e) {
    // The id exists in another business: RLS hides it, so it cannot be updated from here.
    if (pgCode(e) === '42501' || pgCode(e) === PG.uniqueViolation) return res.status(409).json({ code: 'CONFLICT', message: 'This id is already in use.' });
    throw e;
  }
}

customerRoutes.post('/', canWrite, (req, res) => save(req, res, req.body?.id ?? 'c_' + crypto.randomUUID(), 201));
customerRoutes.put('/:id', canWrite, (req, res) => save(req, res, param(req, 'id'), 200));

customerRoutes.delete('/:id', canWrite, async (req, res) => {
  const rows = await inBusiness(req, tx => tx.delete(customers).where(eq(customers.id, param(req, 'id'))).returning({ id: customers.id }));
  return rows.length ? res.status(204).end() : notFound(res, 'Customer');
});
